<?php $basisLabels = ['principal_amount' => 'کل قرارداد', 'financed_amount' => 'تأمین مالی‌شده', 'profit_amount' => 'سود قرارداد', 'collected_amount' => 'وصول‌شده']; ?>
<div class="proma-accounting proma-accounting-commissions">
  <header class="proma-accounting-page-header"><div><span class="proma-accounting-eyebrow">خروجی محاسبات</span><h2>کمیسیون فروش</h2><p>مبلغ مبنا، اثر محدودیت‌ها و وضعیت ثبت هر کمیسیون را مشاهده کنید.</p></div><a class="btn btn-light" href="<?= e(url('plugin/accounting/settings')) ?>#commission-preview"><i data-feather="calculator"></i><span>پیش‌نمایش</span></a></header>
  <section class="proma-accounting-panel"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>قرارداد</th><th>فروشنده</th><th>قانون</th><th>مبنای محاسبه</th><th>کمیسیون اولیه</th><th>کمیسیون نهایی</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach (($commissions ?? []) as $commission): ?><tr><td><strong><?= e($commission['contract_number']) ?></strong></td><td><?= e($commission['seller_name'] ?: 'تخصیص نشده') ?></td><td><?= ($commission['rule_source'] ?? 'default') === 'seller' ? 'اختصاصی' : 'پیش‌فرض' ?></td><td><?= e($basisLabels[$commission['basis_type']] ?? $commission['basis_type']) ?><small class="d-block text-muted"><?= money_toman($commission['basis_amount']) ?></small></td><td><?= money_toman($commission['raw_commission'] ?? $commission['calculated_amount']) ?></td><td><strong><?= money_toman($commission['calculated_amount']) ?></strong></td><td><span class="proma-accounting-status <?= ($commission['status'] ?? '') === 'posted' ? 'is-active' : 'is-pending' ?>"><?= e($commission['status']) ?></span></td><td><div class="proma-accounting-row-actions"><?php if (($commission['status'] ?? '') === 'pending'): ?><form method="post" action="<?= e(url('plugin/accounting/commissions/approve/' . (int) $commission['id'])) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-primary" type="submit">تأیید</button></form><?php elseif (in_array($commission['status'] ?? '', ['payable','approved'], true)): ?><form method="post" action="<?= e(url('plugin/accounting/commissions/post/' . (int) $commission['id'])) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-primary" type="submit">ثبت در حساب</button></form><?php endif; ?><?php if (!in_array($commission['status'] ?? '', ['reversed','cancelled'], true)): ?><form method="post" action="<?= e(url('plugin/accounting/commissions/reverse/' . (int) $commission['id'])) ?>" class="proma-accounting-inline-action" data-accounting-confirm="کمیسیون با سند معکوس اصلاح شود؟"><?= csrf_field() ?><div class="proma-accounting-control"><input name="reason" required placeholder="علت اصلاح"></div><button class="btn btn-sm btn-light" type="submit"><i data-feather="rotate-ccw"></i></button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (empty($commissions)): ?><tr><td colspan="8" class="empty">کمیسیونی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div><?= render_pagination($pagination ?? [], static function ($page) { return url('plugin/accounting/commissions', ['page' => $page]); }) ?></section>
</div>
